{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "Niraparib had an absolute oral bioavailability of 72.7% in cancer patients after a 300 mg oral dose; it shares the basic piperidine and heteroaromatic amide features of the query, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Maraviroc had an absolute oral bioavailability of 23% at 100 mg in healthy volunteers; it shares a basic amine, amide, and heteroaromatic/lipophilic framework with the query, supporting F above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Elinzanetant had a dose-independent oral bioavailability of 36.7% in 366 subjects; its basic amine/amide/heteroaromatic structure supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "MK-8628, a thiazole-containing heteroaromatic amide, was reported to have good oral bioavailability in humans, supporting high F for the similarly heteroaromatic amide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Pradigastat showed moderate absolute oral bioavailability of about 40% in humans; despite a carboxylic acid, its lipophilic aromatic/amide character supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "KNI-272, a peptidomimetic with amide and thioether features, had absolute oral bioavailability of about 55% in adult patients, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic heteroaromatic amide with a basic piperidine, resembling niraparib, maraviroc, elinzanetant, MK-8628, and pradigastat, all of which show human absolute oral bioavailability above 20% (23-73%). Low-F nucleoside analogues are structurally distant and do not override this supportive evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "Metabolic stability of the thioether and amide moieties in humans is not directly evidenced.",
    "Low-F didanosine records are for a polar acid-labile nucleoside and have limited structural transferability.",
    "Food and formulation effects on the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

